mapper.sql:
SELECT ptm.id, pm.process_instance_id, pm.process_definition_id, pm.process_version , pm.process_status , pd.process_name , pm.business_id , pm.business_code , pm.business_name , pm.act_process_definition_id , ptm.cur_approve_id , ptm.cur_activity_id, ptm.cur_activity_name, ptm.task_id, ptm.task_status, ptm.cur_approve_name AS cur_approve_name, concat(wm.detail_url,pm.business_id) as detail_url, pm.create_time as create_time FROM process_task_management AS ptm LEFT JOIN process_management AS pm on pm.process_instance_id = ptm.process_instance_id LEFT JOIN work_menu AS wm on pm.business_key = wm.module_code LEFT JOIN process_definition pd on pd.id = pm.process_definition_id where ptm.task_status = 'approveIng'
and pd.process_name ilike concat('%', #{param.processName},'%')
and pm.business_name in
#{businessName}
and pm.process_version = #{param.processVersion}
and pm.process_status in
#{processStatus}

mapper.select:
AND approve_status = 'approveIng' AND pm.business_id = #{businessId} AND pm.business_key = #{businessKey} AND ptm.task_status = 'approveIng'
AND ptm.cur_approve_id = #{userId}
ORDER BY ptm.create_time ASC LIMIT 1



    and ptm.id in

        #{id}


order by ptm.create_time desc
